INSERT INTO `packages` (`id`, `name`, `slug`, `price`, `image`, `description`, `benefits`, `created_at`, `updated_at`) VALUES
(1, 'Bedroom Hero', 'beginner', 200000, 'packages/2025-10-29_14-31-14_pk2aD9njGAQr4xaQ.jpeg', 'For those who want to learn at their own pace and master the essentials. Perfect if you just want to jam your favorite songs straight from your bedroom', 'Access to all lessons (Level 1–4)\r\nExclusive Song Breakdowns from TikTok & Instagram\r\n1x Personal Coaching Session — get direct feedback on your progress', '2025-10-29 14:31:14', '2025-10-29 14:31:14'),
(2, 'Stage Hero', 'intermediate', 250000, 'packages/2025-10-29_14-32-19_cE9KAimp1Tmg62bE.jpeg', 'Take your skills further with deeper coaching and exclusive learning materials. Perfect for beginners who want to grow faster and play with real confidence on stage', 'Everything from Bedroom Hero\r\n2x Personal Coaching Sessions — double the feedback, double the growth\r\n\r\n💡 Why Choose Stage Hero?\r\nGet two personalized coaching sessions for only Rp50,000 more —\r\nthat’s extra value and faster progress right from your first lesson!\r\n🔥 Most Popular — Designed for Serious Learners', '2025-10-29 14:32:19', '2025-10-29 14:32:19'),
(3, 'Upgrade Intermediate', 'upgrade-intermediate', 50000, NULL, 'Upgrade from Beginner to Intermediate — bayar selisih harga saja.', 'Upgrade fee to move from Beginner to Intermediate.', '2025-10-30 21:03:37', '2025-10-30 21:03:37');
